<div class="mb-4"><a href="/app/<?= e($module) ?>" class="text-decoration-none">← Torna all'elenco</a><h1 class="h3 mt-2"><?= $id?'Modifica':'Nuovo' ?> <?= e(rtrim(ucfirst($module),'i')) ?></h1></div>
<?php foreach($errors as $error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endforeach ?>
<form method="post" action="/app/<?= e($module) ?><?= $id?'/'.(int)$id:'' ?>" class="card border-0 shadow-sm"><div class="card-body p-4"><input type="hidden" name="_csrf" value="<?= e($csrf->token()) ?>"><div class="row g-3">
<?php foreach($record as $key=>$value): if(in_array($key,['id','azienda_id','creato_il','aggiornato_il','archiviato_at'])) continue; ?><div class="col-md-6"><label class="form-label" for="<?= e($key) ?>"><?= e(ucfirst(str_replace('_',' ',$key))) ?></label><?php if(in_array($key,['descrizione','note','rilevazioni','trattamenti_consigliati','prodotti','precauzioni','voci'])): ?><textarea class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" rows="3"><?= e((string)$value) ?></textarea><?php elseif(in_array($key,['cliente_id','sede_id','operatore_id','assegnato_a'])): ?><select class="form-select" id="<?= e($key) ?>" name="<?= e($key) ?>"><option value="">Seleziona…</option><?php $opts=$key==='cliente_id'?$clienti:($key==='sede_id'?$sedi:$utenti); foreach($opts as $opt): $oid=$opt['id']; $label=$opt['denominazione']??(($opt['cognome']??'')?trim(($opt['nome']??'').' '.($opt['cognome']??'')):($opt['nome']??('Sede '.$oid))); ?><option value="<?= (int)$oid ?>" <?= (string)$value===(string)$oid?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select><?php elseif(in_array($key,['stato','tipo','modalita'])): $options=$key==='stato'?($module==='sopralluoghi'?$stati['sopralluogo_stato']:$stati['preventivo_stato']):($key==='tipo'?$stati['calendario_tipo']:['presenza'=>'In presenza','remoto'=>'Da remoto']); ?><select class="form-select" id="<?= e($key) ?>" name="<?= e($key) ?>"><?php foreach($options as $ov=>$ol): ?><option value="<?= e((string)$ov) ?>" <?= (string)$value===(string)$ov?'selected':'' ?>><?= e($ol) ?></option><?php endforeach ?></select><?php else: $type=str_contains($key,'pianificato')||$key==='inizio'||$key==='fine'?'datetime-local':(str_contains($key,'validita')?'date':(in_array($key,['imponibile','iva','sconto','costo_stimato'])?'number':'text')); ?><input class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" type="<?= $type ?>" value="<?= e((string)$value) ?>" <?= $type==='number'?'step="0.01"':'' ?>><?php endif ?></div><?php endforeach ?>
</div><div class="mt-4 d-flex gap-2"><button class="btn btn-primary">Salva</button><a class="btn btn-outline-secondary" href="/app/<?= e($module) ?>">Annulla</a></div></div></form>
